function canVisitAll(rooms: number[][]): boolean {
  const seen = new Array(rooms.length).fill(false);
  seen[0] = true;
  const stack = [0];
  let opened = 1;
  while (stack.length) {
    const room = stack.pop()!;
    for (const key of rooms[room]) {
      if (!seen[key]) {
        seen[key] = true;
        opened++;
        stack.push(key);
      }
    }
  }
  return opened === rooms.length;
}

