function canVisitAll(rooms: number[][]): boolean {
  const seen = new Set<number>([0]);
  const queue = [0];
  for (let head = 0; head < queue.length; head++) {
    for (const key of rooms[queue[head]]) {
      if (!seen.has(key)) {
        seen.add(key);
        queue.push(key);
      }
    }
  }
  return seen.size === rooms.length;
}

